def price:
  if . == "CPU_USAGE" then 0.0004632
  elif . == "MEMORY_USAGE_GB" then 0.0002316
  elif . == "DISK_USAGE_GB" then 0.0000036
  elif . == "NETWORK_TX_GB" then 0.05
  else null end;
def resource($id):
  if $id == "2959d509-c829-4420-8650-e72827d88170" then "Metabase"
  elif $id == "6ba627ff-bc6d-41e7-8182-6c0f1fb03998" then "Postgres + volume"
  elif $id == "00000000-0000-0000-0000-000000000000" then "Unassigned volume"
  elif $id == null then "Unallocated"
  else "Other / removed service " + $id[0:8] end;
if .errors then error(.errors | tostring)
elif .data.usage == null then error("Railway usage unavailable")
else
  [.data.usage[] | .measurement as $measurement |
    ($measurement | price) as $rate |
    select($rate != null) |
    {id:.tags.serviceId, cost:(.value * $rate)}] |
  group_by(.id)[] |
  {Resource:resource(.[0].id), Cost:(map(.cost)|add), Currency:"USD"}
end

def seconds: sub("[.][0-9]+Z$";"Z") | fromdateiso8601;
def rate:
  if . == "CPU_USAGE" then 0.00000772
  elif . == "MEMORY_USAGE_GB" then 0.00000386
  elif . == "DISK_USAGE_GB" then 0.00000006
  else null end;
if .errors then error(.errors | tostring)
elif .data.workspace.customer.billingPeriod.start == null then error("Railway billing period unavailable")
elif .data.services == null or .data.volumes == null then error("Railway usage metrics unavailable")
else
  (.data.workspace.customer.billingPeriod.start | seconds) as $cycle_start |
  [(.data.services[]?, .data.volumes[]?) | .measurement as $measurement |
    ($measurement | rate) as $rate |
    select($rate != null) |
    .values[]? | select(.ts >= $cycle_start) |
    {day:((((.ts + 28800) / 86400 | floor) * 86400 - 28800) * 1000),
     cost:(.value * 3600 * $rate)}] |
  group_by(.day)[] |
  {Time:.[0].day, EstimatedUSD:(map(.cost)|add)}
end

